<?php
namespace App\Http\Controllers\Auth;
use App\Http\Controllers\Controller; use App\Models\User; use Illuminate\Auth\Events\Registered; use Illuminate\Http\Request; use Illuminate\Support\Facades\Auth; use Illuminate\Support\Facades\Hash; use Illuminate\Support\Facades\Password; use Illuminate\Support\Str;
class AuthController extends Controller { public function show(){return view('auth.login');} public function registerForm(){return view('auth.register');} public function login(Request $r){$c=$r->validate(['email'=>'required|email','password'=>'required']); if(Auth::attempt($c,$r->boolean('remember'))){$r->session()->regenerate();return redirect()->intended(Auth::user()->is_admin?route('admin.dashboard'):route('account.dashboard'));} return back()->withErrors(['email'=>'Invalid credentials.'])->onlyInput('email');} public function register(Request $r){$d=$r->validate(['name'=>'required|max:120','email'=>'required|email|unique:users','phone'=>'nullable|max:40','password'=>'required|min:8|confirmed']);$u=User::create($d); event(new Registered($u)); Auth::login($u);return redirect()->route('account.dashboard')->with('success','Account created. Please verify your email when mail is configured.');} public function forgotForm(){return view('auth.forgot');} public function forgot(Request $r){$r->validate(['email'=>'required|email']);$status=Password::sendResetLink($r->only('email'));return $status===Password::RESET_LINK_SENT?back()->with('success',__($status)):back()->withErrors(['email'=>__($status)]);} public function resetForm(Request $r,string $token){return view('auth.reset',['token'=>$token,'email'=>$r->email]);} public function reset(Request $r){$r->validate(['token'=>'required','email'=>'required|email','password'=>'required|min:8|confirmed']);$status=Password::reset($r->only('email','password','password_confirmation','token'),function($u,$password){$u->forceFill(['password'=>Hash::make($password),'remember_token'=>Str::random(60)])->save();});return $status===Password::PASSWORD_RESET?redirect()->route('login')->with('success',__($status)):back()->withErrors(['email'=>__($status)]);} public function logout(Request $r){Auth::logout();$r->session()->invalidate();$r->session()->regenerateToken();return redirect('/');} }
